for p in (ROOT/'src/lib/technical-education/lessons').glob('*.json'):
 if p.name.startswith(('M10','M11')):
  p.write_text(re.sub('\u2066([^\u2069]*)\u2069',lambda m:'\u2066'+m[1].replace(' ','\u00a0')+'\u2069',p.read_text()))
